<script setup lang="ts">import type {Ranking} from '../types/domain';import {number} from '../utils/format';defineProps<{rows:Ranking[]}>();</script><template><div class="table-scroll"><table><thead><tr><th>备选方案</th><th>名次</th><th>贴近度</th><th>到优 / 劣理想点距离</th><th>单权重扰动名次</th></tr></thead><tbody><tr v-for="r in rows" :key="r.alternative_id"><td><b>{{r.name}}</b><small>{{r.alternative_id}}</small></td><td><span :class="['rank',{best:r.rank===1}]">{{r.rank??'—'}}</span></td><td>{{number(r.score,4)}}</td><td>{{number(r.d_plus,4)}} / {{number(r.d_minus,4)}}</td><td>{{r.min_rank==null?'不可排名':r.min_rank+'—'+r.max_rank}}</td></tr></tbody></table></div></template>
